#!/bin/sh
# Install the Opportunity Radar LaunchAgents (sentinel, discovery, digest, backup).
# Thin wrapper: the plists are generated by `radar launchd install` with absolute paths and
# no secrets (tokens come from the Keychain: `radar secrets set TELEGRAM_BOT_TOKEN`, etc.).
# Usage: scripts/install_launchd.sh [--dry-run] [--no-load]
set -eu
cd "$(dirname "$0")/.."
exec uv run radar launchd install "$@"
